<?php
require __DIR__ . '/bootstrap.php';
$slug=trim((string)($_GET['slug']??''));$site=$slug?site_by_slug($slug):null;
if(!$site){http_response_code(404);render_header('Site introuvable');render_nav();?><main class="section-shell empty-state"><h1>Ce site n’existe pas.</h1><a class="btn btn-primary" href="<?=e(app_url())?>">Retour à Nova CMS</a></main><?php render_footer();exit;}
$q=trim((string)($_GET['q']??''));$articles=site_articles((int)$site['id'],true);if($q!=='')$articles=array_values(array_filter($articles,fn($a)=>str_contains(mb_strtolower($a['title'].' '.$a['content']),mb_strtolower($q))));
render_header($site['name'],$site['tagline']?:$site['bio']);
?>
<div class="site-theme" style="--site-accent:<?=e(valid_accent($site['accent']))?>"><header class="mini-nav section-shell"><a class="mini-brand" href="<?=e(app_url('site.php?slug='.rawurlencode($site['slug'])))?>"><img src="<?=e(safe_asset_url($site['avatar'],'assets/images/avatar-default.svg'))?>" alt=""><span><?=e($site['name'])?></span></a><div><a href="<?=e(app_url())?>">Nova CMS</a><a class="mini-admin" href="<?=e(app_url('login.php'))?>">Dashboard</a></div></header><main class="creator-site section-shell"><section class="site-hero"><div class="site-cover"><img src="<?=e(safe_asset_url($site['cover_image'],'assets/images/cover-code.svg'))?>" alt=""></div><div class="site-intro"><div><span class="eyebrow-text">@<?=e($site['slug'])?></span><h1><?=e($site['name'])?></h1><p class="site-tagline"><?=e($site['tagline'])?></p><p><?=e($site['bio'])?></p></div><img class="site-avatar-big" src="<?=e(safe_asset_url($site['avatar'],'assets/images/avatar-default.svg'))?>" alt=""></div></section><section class="site-content"><div class="site-content-head"><div><span class="eyebrow-text">PUBLICATIONS</span><h2>Dernières notes</h2></div><form class="site-search"><input type="hidden" name="slug" value="<?=e($site['slug'])?>"><input name="q" value="<?=e($q)?>" placeholder="Rechercher…"></form></div><?php if(!$articles):?><div class="empty-state compact"><h3>Aucune publication pour le moment.</h3><p>Les nouveaux articles apparaîtront ici.</p></div><?php else:?><div class="post-grid"><?php foreach($articles as $article):?><article class="post-card"><a class="post-image" href="<?=e(app_url('article.php?site='.rawurlencode($site['slug']).'&slug='.rawurlencode($article['slug'])))?>"><img src="<?=e(safe_asset_url($article['image']))?>" alt=""></a><div class="post-body"><div class="post-kicker"><span><?=e($article['category'])?></span><time><?=e(substr((string)$article['published_at'],0,10))?></time></div><h3><a href="<?=e(app_url('article.php?site='.rawurlencode($site['slug']).'&slug='.rawurlencode($article['slug'])))?>"><?=e($article['title'])?></a></h3><p><?=e($article['excerpt']?:excerpt($article['content']))?></p><a class="text-link" href="<?=e(app_url('article.php?site='.rawurlencode($site['slug']).'&slug='.rawurlencode($article['slug'])))?>">Lire l’article →</a></div></article><?php endforeach;?></div><?php endif;?></section></main><footer class="mini-footer section-shell"><span>Propulsé par <a href="<?=e(app_url())?>">Nova CMS</a></span><span>Open source · PHP</span></footer></div>
